WITH prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC) AS prev_paid_at FROM payments), flagged AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY method ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, status, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN status = 'FAILED' THEN 1 END), 0), 2) AS amount_per_failed, SUM(new_group_flag) AS total_new_group_flag, MAX(paid_at) AS ended_at, GROUPING_ID() AS gid FROM sessionized GROUP BY CUBE (CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END, status) ORDER BY total_new_group_flag DESC NULLS FIRST;
